class Solution {
public:
    int numDifferentIntegers(string word) {
        unordered_set<string> unique;
        int n = word.size(), i = 0;
        while (i < n) {
            if (isdigit(word[i])) {
                int start = i;
                while (i < n && isdigit(word[i])) i++;
                while (start < i - 1 && word[start] == '0') start++;
                unique.insert(word.substr(start, i - start));
            } else {
                i++;
            }
        }
        return unique.size();
    }
};

import java.util.*;

class Solution {
    public int numDifferentIntegers(String word) {
        Set<String> unique = new HashSet<>();
        int n = word.length(), i = 0;
        while (i < n) {
            if (Character.isDigit(word.charAt(i))) {
                int start = i;
                while (i < n && Character.isDigit(word.charAt(i))) i++;
                while (start < i - 1 && word.charAt(start) == '0') start++;
                unique.add(word.substring(start, i));
            } else {
                i++;
            }
        }
        return unique.size();
    }
}

/**
 * @param {string} word
 * @return {number}
 */
var numDifferentIntegers = function(word) {
    const s = word.replace(/[a-z]/g, ' ').trim();
    if (!s) return 0;
    const tokens = s.split(/\s+/);
    const seen = new Set();
    for (const token of tokens) {
        seen.add(token.replace(/^0+/, '') || '0');
    }
    return seen.size;
};
